#ifndef COD1_ACTOR_FACE_UNMOUNTED14_H
#define COD1_ACTOR_FACE_UNMOUNTED14_H
#include "cod1_actor_unmounted_tree14.h"
#include "cod1_actor_face_unmounted14_defs.h"
/* Separate owned original face bank. No actor clock, note delivery, mutation,
 * additive face overlay or borrowed-resource Free. Caller owns lease/FS. */
typedef struct {c1aut14Bank_t base;c1ar14Root_t*faceRoot[C1AFU14_FACES];c1ab14Clip_t*faceBody[C1AFU14_FACES];} c1afu14Bank_t;
static void C1AFU14_Free(c1afu14Bank_t*b){unsigned i;if(!b)return;C1AUT14_Free(&b->base);for(i=0;i<C1AFU14_FACES;i++){C1AR14_Free(b->faceRoot[i]);C1AB14_Free(b->faceBody[i]);b->faceRoot[i]=NULL;b->faceBody[i]=NULL;}}
static int C1AFU14_ValidFace(unsigned i,const c1ar14Root_t*r,const c1ab14Clip_t*c){static const unsigned frames[5]={136,63,149,125,81},flags[5]={0,0,1,1,0};unsigned bones=i<2?23:19;if(i>=5||!r||!c)return 0;return r->magic==C1AR14_MAGIC&&c->magic==C1AB14_MAGIC&&r->frames==frames[i]&&c->frames==frames[i]&&r->flags==flags[i]&&c->flags==flags[i]&&r->fps==30&&c->fps==30&&r->bones==bones&&c->bones==bones&&r->serializedFrames==frames[i]+flags[i]&&c->serializedFrames==r->serializedFrames&&r->intervals+1==r->serializedFrames&&c->intervals==r->intervals&&r->noteCount==(i<2?1u:0u)&&(i>=2||(!strcmp(r->notes[0].name,"dialogue")&&r->notes[0].frame==5));}
/* Root decoder validates the complete stream. This bounded second walk proves
 * actual named note identity/frame rather than treating noteCount as enough. */
static int C1AFU14_Notes(unsigned index,const void*raw,size_t size,const c1ar14Root_t*root){c1ar14Reader_t r;unsigned i,n,k,bytes;unsigned char simple[16];char name[128];r.p=raw;r.n=size;r.at=root->prefixBytes;r.ok=1;bytes=(root->bones+7)/8;if(!C1AR14_Take(&r,bytes))return 0;for(i=0;i<bytes;i++)simple[i]=(unsigned char)C1AR14_U8(&r);for(i=0;i<root->bones;i++)if(!C1AR14_String(&r))return 0;for(i=0;i<root->bones;i++){n=C1AR14_U16(&r);if(!C1AR14_Indices(&r,n,root->serializedFrames,NULL)||!C1AR14_Take(&r,n*((simple[i/8]&(1u<<(i%8)))?2u:6u)))return 0;n=C1AR14_U16(&r);if(!C1AR14_Indices(&r,n,root->serializedFrames,NULL)||!C1AR14_Take(&r,n*12u))return 0;}n=C1AR14_U8(&r);if(n!=(index<2?1u:0u))return 0;for(i=0;i<n;i++){memset(name,0,sizeof(name));for(k=0;k<128;k++){name[k]=(char)C1AR14_U8(&r);if(!name[k])break;}if(k==128||strcmp(name,"dialogue")||C1AR14_U16(&r)!=5)return 0;}return r.ok&&r.at==r.n;}
static int C1AFU14_Add(c1afu14Bank_t*b,unsigned i,const void*raw,size_t size){c1ar14Root_t*r=NULL;c1ab14Clip_t*c=NULL;if(!b||i>=47||!raw||!size||C1AB14_Overlap(b,sizeof(*b),raw,size))return 0;if(i<42)return C1AUT14_Add(&b->base,i,raw,size);i-=42;if(b->faceRoot[i]||b->faceBody[i])return 0;if(!C1AR14_Decode(raw,size,&r)||!C1AB14_Decode(raw,size,&c)||!C1AFU14_ValidFace(i,r,c)||!C1AFU14_Notes(i,raw,size,r)){C1AR14_Free(r);C1AB14_Free(c);return 0;}b->faceRoot[i]=r;b->faceBody[i]=c;return 1;}
static int C1AFU14_Ready(const c1afu14Bank_t*b){unsigned i;if(!b||!C1AUT14_Ready(&b->base))return 0;for(i=0;i<5;i++)if(!C1AFU14_ValidFace(i,b->faceRoot[i],b->faceBody[i]))return 0;return 1;}
static int C1AFU14_Nodes(const float current[98],const float phases[2][21],c1ast14Node_t out[56]){c1ast14Node_t staged[56];unsigned i,g;if(!current||!phases||!out||C1AB14_Overlap(current,98*4,out,sizeof(staged))||C1AB14_Overlap(phases,42*4,out,sizeof(staged))||C1AB14_Overlap(c1afu14Definitions,sizeof(c1afu14Definitions),out,sizeof(staged)))return 0;for(i=0;i<98;i++)if(!(current[i]>=0&&current[i]<=1)||(i>=56&&current[i]!=0))return 0;if(current[0]!=1)return 0;for(g=0;g<2;g++)for(i=0;i<21;i++)if(!(phases[g][i]>=0&&phases[g][i]<=1)||((g||i>=7)&&phases[g][i]!=0))return 0;for(i=0;i<56;i++){const c1afu14Definition_t*d=c1afu14Definitions+i;staged[i].ordinal=d->ordinal;staged[i].parent=d->parent;staged[i].leaf=d->leaf;staged[i].currentWeight=current[i];staged[i].phase=d->phase<0?0:phases[0][d->phase];}memcpy(out,staged,sizeof(staged));return 1;}
static int C1AFU14_Bank(const c1ad14Resource_t*r,const c1afu14Bank_t*b,c1ast14Bank_t*out){c1ast14Bank_t staged;unsigned i,k;if(!r||!r->assembly||!b||!out||!C1AFU14_Ready(b)||C1AB14_Overlap(r,sizeof(*r),out,sizeof(*out))||C1AB14_Overlap(r->assembly,sizeof(*r->assembly),out,sizeof(*out))||C1AB14_Overlap(b,sizeof(*b),out,sizeof(*out)))return 0;
 for(i=0;i<r->assembly->count;i++)if(r->raw[i]&&C1AB14_Overlap(r->raw[i],sizeof(*r->raw[i]),out,sizeof(*out)))return 0;
 for(i=0;i<47;i++){const c1ab14Clip_t*c=i<2?b->base.body[i]:i<42?b->base.look.body[i-2]:b->faceBody[i-42];const c1ar14Root_t*root=i<2?b->base.root[i]:i<42?b->base.look.root[i-2]:b->faceRoot[i-42];if(C1AB14_Overlap(c,sizeof(*c),out,sizeof(*out))||C1AB14_Overlap(root,sizeof(*root),out,sizeof(*out)))return 0;for(k=0;k<c->bones;k++){const c1ab14Bone_t*v=c->bone+k;if(C1AB14_Overlap(v->qi,v->nq*2,out,sizeof(*out))||C1AB14_Overlap(v->q,v->nq*8,out,sizeof(*out))||C1AB14_Overlap(v->ti,v->nt*2,out,sizeof(*out))||C1AB14_Overlap(v->t,v->nt*12,out,sizeof(*out)))return 0;}}
 if(!C1AUT14_Bank(r,&b->base,&staged))return 0;staged.count=47;for(i=0;i<5;i++){staged.clip[i+42]=b->faceBody[i];if(!C1AD14_Map(r,staged.clip[i+42],staged.map[i+42]))return 0;}*out=staged;return 1;}
#endif
